      if(comp.id==='daily'){for(const d of days(c))out.push({id:'daily-'+d.number,type:'daily',label:'Day '+d.number+' · '+d.kind,week:d.week,day:d.number,offset:d.number-1,owner:comp.owner});}
      else if(once.has(comp.id))out.push({id:comp.id,type:comp.id,label:comp.label,week:1,offset:comp.id==='next'?c.profile.duration:comp.id==='hosts'?-28:comp.id==='landing'?-14:comp.id==='branding'?-21:0,owner:comp.owner});
      else for(const w of ww)out.push({id:comp.id+'-'+w.number,type:comp.id,label:'Week '+w.number+' · '+comp.label,week:w.number,offset:(w.number-1)*7,owner:comp.owner});
